  ?z brick:hasTag "Core_ZN".
  ?z brick:isPointOf ?temp.  ?temp ref:hasTimeseriesId ?a.
  ?z brick:isPointOf ?set.  ?set ref:hasTimeseriesId ?b.
}

SELECT ?z ?temp ?set WHERE {
  ?z a brick:Zone.
  ?z brick:hasTag "Core_ZN".
  OPTIONAL { ?z brick:isPointOf ?temp. ?temp a brick:AirTemperatureSensor. }
  OPTIONAL { ?z brick:isPointOf ?set. ?set a brick:TemperatureSetpoint }
}

